<template>
  <div class="manual-execution">
    <a-empty v-if="!projectId" description="请先选择项目" />
    <template v-else-if="!selectedRun">
      <header class="page-heading"><div><h2>用例执行</h2><span>{{ runs.length }} 个执行任务</span></div><a-button v-if="isManager" type="primary" @click="openCreate"><template #icon><icon-plus /></template>分派用例</a-button></header>
      <section class="surface"><div class="toolbar"><a-input-search v-model="keyword" allow-clear placeholder="搜索执行批次" @search="loadRuns" @clear="loadRuns" /></div>
        <a-table v-if="runs.length || loading" :columns="runColumns" :data="runs" :loading="loading" row-key="id" :pagination="false" :bordered="{ cell: true }">
          <template #name="{ record }"><a-link @click="openRun(record)">{{ record.name }}</a-link><div class="subtle">{{ record.description || '未填写说明' }}</div></template>
          <template #assignee="{ record }">{{ record.assignments?.[0]?.assignee_detail?.username || '-' }}</template>
          <template #progress="{ record }"><a-progress :percent="record.total_count ? (record.passed_count + record.failed_count) / record.total_count : 0" :show-text="false" size="small" /><span class="subtle">{{ record.passed_count + record.failed_count }}/{{ record.total_count }}（{{ progressPercent(record) }}%）</span></template>
          <template #status="{ record }"><a-tag :color="runStatusColor(record.status)">{{ runStatusText(record.status) }}</a-tag></template>
          <template #createdAt="{ record }">{{ formatRunDate(record.created_at) }}</template>
          <template #actions="{ record }"><a-space><a-button type="text" @click="openRun(record)">进入任务</a-button><a-button v-if="isManager" type="text" @click="openTaskEdit(record)">编辑</a-button><a-button v-if="isManager" type="text" status="danger" @click="removeTask(record)">删除</a-button></a-space></template>
        </a-table><a-empty v-else description="暂无执行任务" class="empty" /></section>
    </template>
    <template v-else>
      <header class="page-heading"><div class="title-line"><a-button type="text" @click="selectedRun = null"><template #icon><icon-left /></template>返回任务列表</a-button><div><h2>{{ selectedRun.name }}</h2><span>{{ selectedRun.total_count }} 条用例，{{ selectedRun.pending_count }} 条待执行</span></div></div><a-space><a-tag color="green">通过 {{ selectedRun.passed_count }}</a-tag><a-tag color="red">不通过 {{ selectedRun.failed_count }}</a-tag></a-space></header>
      <section class="surface"><a-table :columns="caseColumns" :data="selectedRun.assignments || []" row-key="id" :pagination="false" :bordered="{ cell: true }"><template #case="{ record }"><strong>{{ record.testcase_detail?.name }}</strong><div class="subtle">#{{ record.testcase }} {{ record.testcase_detail?.module_detail || '未分配模块' }}</div></template><template #result="{ record }"><a-tag :color="resultColor(record.status)">{{ resultText(record.status) }}</a-tag></template><template #reason="{ record }">{{ record.failure_reason || '-' }}</template><template #actions="{ record }"><a-button type="text" @click="openCase(record)">{{ record.status === 'pending' ? '执行' : '查看/更新' }}</a-button></template></a-table></section>
    </template>

    <a-modal v-model:visible="createVisible" title="分派测试用例" :ok-loading="saving" @ok="createRun"><a-form :model="form" layout="vertical"><a-form-item label="执行批次" required><a-input v-model="form.name" placeholder="例如：V2.4 回归测试" /></a-form-item><a-form-item label="测试人员" required><a-select v-model="form.assignee_id" placeholder="请选择测试人员"><a-option v-for="member in members" :key="member.user" :value="member.user">{{ member.user_detail.username }}</a-option></a-select></a-form-item><a-form-item label="测试用例" required><div class="picker"><div class="picker-head">模块与用例 <a-tag color="arcoblue">已选 {{ form.testcase_ids.length }} 条</a-tag></div><a-tree :data="caseTree" checkable block-node :checked-keys="form.testcase_ids" :field-names="{ key: 'key', title: 'title', children: 'children' }" @check="onTreeCheck" /></div></a-form-item><a-form-item label="说明"><a-textarea v-model="form.description" :auto-size="{ minRows: 2, maxRows: 4 }" /></a-form-item></a-form></a-modal>
    <a-modal v-model:visible="editVisible" title="编辑执行任务" :ok-loading="saving" @ok="saveTaskEdit"><a-form :model="editForm" layout="vertical"><a-form-item label="执行批次" required><a-input v-model="editForm.name" /></a-form-item><a-form-item label="说明"><a-textarea v-model="editForm.description" :auto-size="{ minRows: 2, maxRows: 4 }" /></a-form-item><a-form-item label="测试用例"><div class="picker"><div class="picker-head">模块与用例 <a-tag color="arcoblue">已选 {{ editCaseIds.length }} 条</a-tag></div><a-tree :data="caseTree" checkable block-node :checked-keys="editCaseIds" :field-names="{ key: 'key', title: 'title', children: 'children' }" @check="onEditTreeCheck" /></div></a-form-item></a-form></a-modal>
    <a-drawer v-model:visible="caseVisible" :width="840" title="执行测试用例"><template v-if="active"><div class="case-nav"><a-button :disabled="activeIndex === 0" @click="goCase(-1)"><template #icon><icon-left /></template>上一条</a-button><span>{{ activeIndex + 1 }} / {{ selectedRun?.assignments?.length || 0 }}</span><a-button :disabled="activeIndex === (selectedRun?.assignments?.length || 1) - 1" @click="goCase(1)">下一条<template #icon><icon-right /></template></a-button></div><h3>{{ active.testcase_detail?.name }}</h3><a-descriptions :column="2" bordered size="small"><a-descriptions-item label="所属模块">{{ active.testcase_detail?.module_detail || '-' }}</a-descriptions-item><a-descriptions-item label="优先级">{{ active.testcase_detail?.level }}</a-descriptions-item></a-descriptions><section class="detail"><h4>前置条件</h4><p>{{ active.testcase_detail?.precondition || '-' }}</p><h4>测试步骤</h4><a-table :columns="stepColumns" :data="active.testcase_detail?.steps || []" :pagination="false" size="small" bordered /><h4>备注</h4><p>{{ active.testcase_detail?.notes || '-' }}</p></section><a-form :model="resultForm" layout="vertical"><a-form-item label="执行结果" required><a-radio-group v-model="resultForm.status"><a-radio value="pass">通过</a-radio><a-radio value="fail">不通过</a-radio><a-radio value="pending">恢复待执行</a-radio></a-radio-group></a-form-item><a-form-item label="失败原因" :required="resultForm.status === 'fail'"><a-textarea v-model="resultForm.failure_reason" :auto-size="{ minRows: 2, maxRows: 4 }" /></a-form-item><a-form-item label="执行备注"><a-textarea v-model="resultForm.comment" :auto-size="{ minRows: 2, maxRows: 4 }" /></a-form-item></a-form></template><template #footer><a-button @click="caseVisible=false">取消</a-button><a-button type="primary" :loading="saving" @click="saveResult">保存结果</a-button></template></a-drawer>
  </div>
</template>
<script setup lang="ts">
import { computed, ref, watch } from 'vue'; import { useRoute } from 'vue-router'; import { Message, Modal } from '@arco-design/web-vue'; import type { TableColumnData } from '@arco-design/web-vue';
import { useProjectStore } from '@/store/projectStore'; import { useAuthStore } from '@/store/authStore'; import { getProjectMembers, type ProjectMember } from '@/services/projectService'; import { getTestCaseList, type TestCase } from '@/services/testcaseService'; import { getTestCaseModules, type TestCaseModule } from '@/services/testcaseModuleService'; import { addManualRunCases, createManualTestRun, deleteManualRun, getManualRuns, removeManualRunCase, submitManualResult, updateManualRun, type ManualResultStatus, type ManualTestAssignment } from '@/services/manualTestExecutionService';
const projectStore=useProjectStore(), authStore=useAuthStore(), route=useRoute(); const projectId=computed(()=>projectStore.currentProjectId); const runs=ref<any[]>([]), selectedRun=ref<any>(null), members=ref<ProjectMember[]>([]), testcases=ref<TestCase[]>([]), modules=ref<TestCaseModule[]>([]); const keyword=ref(''), loading=ref(false), saving=ref(false), createVisible=ref(false), editVisible=ref(false), caseVisible=ref(false), active=ref<ManualTestAssignment|null>(null), activeIndex=ref(0), editingRun=ref<any>(null); const form=ref({name:'',description:'',assignee_id:undefined as number|undefined,testcase_ids:[] as number[]}); const editForm=ref({name:'',description:''}), editCaseIds=ref<number[]>([]); const resultForm=ref({status:'pending' as ManualResultStatus,failure_reason:'',comment:''}); const isManager=computed(()=>authStore.user?.is_staff||members.value.some(m=>m.user===authStore.user?.id&&['owner','admin'].includes(m.role)));
const runColumns:TableColumnData[]=[{title:'执行批次',slotName:'name',width:340},{title:'测试人员',slotName:'assignee',width:150},{title:'进度',slotName:'progress',width:220},{title:'状态',slotName:'status',width:120},{title:'创建时间',slotName:'createdAt',width:180},{title:'操作',slotName:'actions',width:120}]; const caseColumns:TableColumnData[]=[{title:'测试用例',slotName:'case',width:420},{title:'结果',slotName:'result',width:120},{title:'失败原因',slotName:'reason'},{title:'操作',slotName:'actions',width:120}]; const stepColumns:TableColumnData[]=[{title:'步骤',dataIndex:'step_number',width:70},{title:'描述',dataIndex:'description'},{title:'预期结果',dataIndex:'expected_result'}];
const caseTree=computed(()=>{const map=new Map<number,any>(),roots:any[]=[];modules.value.forEach(m=>map.set(m.id,{key:`m-${m.id}`,title:m.name,children:[]}));modules.value.forEach(m=>{const p=m.parent_id??m.parent;p&&map.has(p)?map.get(p).children.push(map.get(m.id)):roots.push(map.get(m.id))});testcases.value.forEach(t=>{const leaf={key:t.id,title:`#${t.id} ${t.name}`};t.module_id&&map.has(t.module_id)?map.get(t.module_id).children.push(leaf):roots.push(leaf)});return roots}); function onTreeCheck(keys:any[]){form.value.testcase_ids=keys.filter(k=>typeof k==='number')}; function onEditTreeCheck(keys:any[]){editCaseIds.value=keys.filter(k=>typeof k==='number')}; const resultText=(s:string)=>({pending:'待执行',pass:'通过',fail:'不通过'}[s]||s); const resultColor=(s:string)=>({pending:'gray',pass:'green',fail:'red'}[s]||'gray'); const runStatusText=(s:string)=>({pending:'待执行',in_progress:'执行中',completed:'已完成'}[s]||s); const runStatusColor=(s:string)=>({pending:'gray',in_progress:'arcoblue',completed:'green'}[s]||'gray');
async function loadRuns(){if(!projectId.value)return;loading.value=true;try{runs.value=await getManualRuns(projectId.value,{search:keyword.value})}catch(e:any){Message.error(e.response?.data?.message||'获取执行任务失败')}finally{loading.value=false}} async function loadOptions(){if(!projectId.value)return;const[a,b,c]=await Promise.all([getProjectMembers(projectId.value),getTestCaseList(projectId.value,{page:1,pageSize:1000}),getTestCaseModules(projectId.value)]);members.value=a.data||[];testcases.value=b.data||[];modules.value=c.data||[]} async function openCreate(){await loadOptions();const ids=String(route.query.testcase_ids||'').split(',').map(Number).filter(Boolean);if(ids.length)form.value.testcase_ids=ids;createVisible.value=true} async function createRun(){if(!projectId.value||!form.value.name||!form.value.assignee_id||!form.value.testcase_ids.length){Message.warning('请填写批次、测试人员并选择用例');return}saving.value=true;try{await createManualTestRun(projectId.value,form.value as any);createVisible.value=false;form.value={name:'',description:'',assignee_id:undefined,testcase_ids:[]};await loadRuns();Message.success('已创建执行任务')}catch(e:any){Message.error(e.response?.data?.message||'分派失败')}finally{saving.value=false}} function openRun(run:any){selectedRun.value=run} function openEdit(run:any){editingRun.value=run;editForm.value={name:run.name,description:run.description||''};editVisible.value=true} async function saveEdit(){if(!projectId.value||!editingRun.value||!editForm.value.name){Message.warning('请填写执行批次');return}saving.value=true;try{await updateManualRun(projectId.value,editingRun.value.id,editForm.value);editVisible.value=false;await loadRuns();Message.success('任务已更新')}catch(e:any){Message.error(e.response?.data?.message||'更新失败')}finally{saving.value=false}} async function removeRun(run:any){if(!projectId.value)return;try{await new Promise<void>((resolve,reject)=>Modal.warning({title:'删除执行任务',content:`确定删除「${run.name}」吗？任务下的执行记录也会删除。`,onOk:()=>resolve(),onCancel:()=>reject()}));await deleteManualRun(projectId.value,run.id);await loadRuns();Message.success('任务已删除')}catch(e:any){if(e)Message.error(e.response?.data?.message||'删除失败')}} function openCase(item:ManualTestAssignment){activeIndex.value=selectedRun.value.assignments.findIndex((x:any)=>x.id===item.id);active.value=item;resultForm.value={status:item.status,failure_reason:item.failure_reason||'',comment:item.comment||''};caseVisible.value=true} function goCase(step:number){openCase(selectedRun.value.assignments[activeIndex.value+step])} async function saveResult(){if(!active.value||!projectId.value)return;if(resultForm.value.status==='fail'&&!resultForm.value.failure_reason.trim()){Message.warning('请填写失败原因');return}saving.value=true;try{const result=await submitManualResult(projectId.value,active.value.id,resultForm.value);selectedRun.value.assignments[activeIndex.value]=result;active.value=result;await loadRuns();Message.success('结果已保存')}catch(e:any){Message.error(e.response?.data?.message||'保存失败')}finally{saving.value=false}} watch(projectId,()=>{selectedRun.value=null;loadRuns();loadOptions()},{immediate:true});
async function openTaskEdit(run:any){await loadOptions();editingRun.value=run;editForm.value={name:run.name,description:run.description||''};editCaseIds.value=(run.assignments||[]).map((item:any)=>item.testcase);editVisible.value=true}
async function addCases(){if(!projectId.value||!editingRun.value)return;const current=new Set((editingRun.value.assignments||[]).map((item:any)=>item.testcase));const ids=editCaseIds.value.filter(id=>!current.has(id));if(!ids.length){Message.warning('请选择尚未加入任务的用例');return}const assigneeId=editingRun.value.assignments?.[0]?.assignee;if(!assigneeId){Message.warning('当前任务没有测试人员');return}saving.value=true;try{editingRun.value=await addManualRunCases(projectId.value,editingRun.value.id,{testcase_ids:ids,assignee_id:assigneeId});editCaseIds.value=[];await loadRuns();Message.success('用例已添加')}catch(e:any){Message.error(e.response?.data?.message||'添加失败')}finally{saving.value=false}}
async function removeCase(item:any){if(!projectId.value||!editingRun.value)return;try{editingRun.value=await removeManualRunCase(projectId.value,editingRun.value.id,item.testcase);await loadRuns();Message.success('用例已删除')}catch(e:any){Message.error(e.response?.data?.message||'删除失败')}}
async function removeTask(run:any){if(!projectId.value)return;try{await new Promise<void>((resolve,reject)=>Modal.confirm({title:'删除执行任务',content:`确定删除「${run.name}」吗？任务下的执行记录也会删除。`,okText:'确定删除',cancelText:'取消',closable:true,hideCancel:false,onOk:()=>resolve(),onCancel:()=>reject()}));await deleteManualRun(projectId.value,run.id);await loadRuns();Message.success('任务已删除')}catch(e:any){if(e)Message.error(e.response?.data?.message||'删除失败')}}
async function saveTaskEdit(){if(!projectId.value||!editingRun.value||!editForm.value.name){Message.warning('请填写执行批次');return}const run=editingRun.value;const currentIds=(run.assignments||[]).map((item:any)=>item.testcase);const selected=new Set(editCaseIds.value);const assigneeId=run.assignments?.[0]?.assignee;saving.value=true;try{await updateManualRun(projectId.value,run.id,editForm.value);for(const testcaseId of currentIds.filter((id:number)=>!selected.has(id))){await removeManualRunCase(projectId.value,run.id,testcaseId)}const additions=editCaseIds.value.filter(id=>!currentIds.includes(id));if(additions.length){if(!assigneeId)throw new Error('当前任务没有测试人员');await addManualRunCases(projectId.value,run.id,{testcase_ids:additions,assignee_id:assigneeId})}editVisible.value=false;await loadRuns();Message.success('任务已更新')}catch(e:any){Message.error(e.response?.data?.message||e.message||'更新失败')}finally{saving.value=false}}
function progressPercent(record:any){return record.total_count?Math.round((record.passed_count+record.failed_count)/record.total_count*100):0}
function formatRunDate(value?:string){if(!value)return '-';const date=new Date(value);if(Number.isNaN(date.getTime()))return value;return `${date.getFullYear()}/${date.getMonth()+1}/${date.getDate()} ${date.getHours()}:${String(date.getMinutes()).padStart(2,'0')}:${String(date.getSeconds()).padStart(2,'0')}`}
</script>
<style scoped>
.manual-execution{min-height:calc(100vh - 64px);padding:24px 32px;background:#f5f7fa}.page-heading{width:100%;margin:0 0 18px;display:flex;align-items:center;justify-content:space-between}.page-heading h2{margin:0;font-size:22px}.page-heading span,.subtle{color:#86909c;font-size:13px}.title-line{display:flex;align-items:center;gap:12px}.surface{width:100%;min-height:calc(100vh - 190px);margin:0;padding:20px 22px;background:#fff;border:1px solid #e5e6eb;border-radius:8px;box-sizing:border-box}.toolbar{display:flex;align-items:center;padding-bottom:18px;margin-bottom:18px;border-bottom:1px solid #f2f3f5}.toolbar :deep(.arco-input-wrapper){width:380px}.surface :deep(.arco-table-th){height:46px;font-size:14px}.surface :deep(.arco-table-td){padding-top:14px;padding-bottom:14px;font-size:14px}.surface :deep(.arco-progress-line){min-width:190px}.empty{padding:140px 0}.picker{height:340px;overflow:auto;padding:10px;border:1px solid #e5e6eb;border-radius:4px;background:#fafbfc}.picker-head{display:flex;justify-content:space-between;padding:0 4px 10px;margin-bottom:8px;border-bottom:1px solid #e5e6eb}.case-nav{display:flex;justify-content:space-between;align-items:center;padding:0 0 16px;border-bottom:1px solid #e5e6eb}.detail h4{margin:22px 0 8px}.detail p{white-space:pre-wrap;line-height:1.7;color:#4e5969}@media (max-width:900px){.manual-execution{padding:16px}.surface{padding:14px;overflow-x:auto}.toolbar :deep(.arco-input-wrapper){width:100%}}
</style>
